import json
import re
from typing import Optional, Any, TypeVar
from datetime import datetime
import logging

logger = logging.getLogger(__name__)
T = TypeVar('T')

def safe_json_parse(text: str, default: T = None) -> T | dict | list:
    """EGRR_PATTERN: Safe JSON parsing with default value."""
    if not text or not text.strip():
        return default

    try:
        return json.loads(text)
    except json.JSONDecodeError as e:
        logger.warning(f'JSON parse error at position {e.pos}: {e.msg}')
        return default

def safe_int(value: Any, default: int = 0) -> int:
    """EGRR_PATTERN: Safe integer conversion."""
    if value is None:
        return default
    try:
        if isinstance(value, str):
            value = value.strip()
        return int(value)
    except (ValueError, TypeError):
        return default

def safe_float(value: Any, default: float = 0.0) -> float:
    """EGRR_PATTERN: Safe float conversion."""
    if value is None:
        return default
    try:
        if isinstance(value, str):
            value = value.strip().replace(',', '')
        return float(value)
    except (ValueError, TypeError):
        return default

def safe_parse_date(date_str: str, formats: list[str] = None) -> Optional[datetime]:
    """EGRR_PATTERN: Safe date parsing with multiple format support."""
    if not date_str:
        return None

    formats = formats or ['%Y-%m-%d', '%Y-%m-%dT%H:%M:%S', '%d/%m/%Y', '%m/%d/%Y']

    for fmt in formats:
        try:
            return datetime.strptime(date_str.strip(), fmt)
        except ValueError:
            continue

    logger.warning(f'Could not parse date: {date_str}')
    return None

